@Timeout(120)
class LmdbIndependentFiniteAnchorJoinPlanningTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SOCIAL_FOLLOWS = VF.createIRI("http://example.com/theme/social/follows");

	@Test
	void plannerCombinesIndependentFiniteUserAnchorsBeforeFollowsBridge(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc");
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			loadSyntheticMutualFollowData(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);

			try (SailRepositoryConnection connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(mutualFollowsQuery())
						.explain(Explanation.Level.Optimized);
				TupleExpr optimized = (TupleExpr) explanation.tupleExpr();

				List<String> executionOrder = new ArrayList<>();
				List<StatementPattern> bridgeMatches = new ArrayList<>(1);
				optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(BindingSetAssignment node) {
						if (node.getBindingNames().contains("u")) {
							executionOrder.add("anchor-u");
						}
						if (node.getBindingNames().contains("v")) {
							executionOrder.add("anchor-v");
						}
					}

					@Override
					public void meet(StatementPattern node) {
						if (bridgeMatches.isEmpty() && isFollowsBridge(node)) {
							bridgeMatches.add(node);
							executionOrder.add("follows-bridge");
						}
						super.meet(node);
					}
				});

				assertTrue(!bridgeMatches.isEmpty(),
						"Expected the optimized q7-style plan to retain the follows bridge. plan=" + optimized);
				StatementPattern bridge = bridgeMatches.getFirst();
				int bridgeIndex = executionOrder.indexOf("follows-bridge");
				assertTrue(executionOrder.contains("anchor-u") && executionOrder.contains("anchor-v"),
						"Expected both finite user anchors in the optimized plan. order=" + executionOrder
								+ ", plan=" + optimized);
				assertTrue(executionOrder.indexOf("anchor-u") < bridgeIndex
						&& executionOrder.indexOf("anchor-v") < bridgeIndex,
						"Independent finite user anchors should be combined before the follows bridge so the bridge "
								+ "binds the full SPO prefix instead of a one-sided range. order=" + executionOrder
								+ ", plan=" + optimized);

				assertEquals("prefixScan",
						bridge.getStringMetricPlanned(TelemetryMetricNames.PLANNED_INDEX_ACCESS_MODE),
						"Both finite domains bind SPO; the absent context keeps the physical access a range: "
								+ bridge);
				assertEquals(3.0d, bridge.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_INDEX_PREFIX_LENGTH),
						0.0d, "The physical range retains the complete three-component SPO prefix");
				assertEquals("[S, P, O]",
						bridge.getStringMetricPlanned(TelemetryMetricNames.PLANNED_LOOKUP_COMPONENTS),
						"Follows bridge should bind subject, predicate, and object: " + bridge);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void repeatedPredicateChainUsesMultiRelationFrontierEvidence(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc");
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			loadSyntheticMutualFollowData(repository);
			LmdbPlannerAwait.rebuildSketchesIfEnabled(store);
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());

			try (SailRepositoryConnection connection = repository.getConnection()) {
				TupleExpr optimized = (TupleExpr) connection.prepareTupleQuery(repeatedFollowsChainQuery())
						.explain(Explanation.Level.Optimized)
						.tupleExpr();
				List<Join> frontierJoins = new ArrayList<>();
				optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(Join node) {
						if (node.getDoubleMetricPlanned("plannedFrontierStateId") > 0.0d) {
							frontierJoins.add(node);
						}
						super.meet(node);
					}
				});

				assertTrue(frontierJoins.stream()
						.mapToDouble(join -> join.getDoubleMetricPlanned("plannedFrontierFactorCount"))
						.max()
						.orElse(0.0d) >= 4.0d,
						"Expected the later repeated-predicate hop to retain the VALUES leaf and all three predicate "
								+ "factors in one Frontier state. plan=" + optimized);
				Set<StatementPattern> actualLeaves = physicalStatementInputs(frontierJoins);
				assertTrue(!actualLeaves.isEmpty(), "Selected Frontier joins must retain physical statement inputs");
				assertEquals(3, actualLeaves.size(), "Each repeated-predicate occurrence must remain a distinct leaf");
				assertTrue(actualLeaves.stream()
						.allMatch(leaf -> SOCIAL_FOLLOWS.equals(leaf.getPredicateVar().getValue())));
				assertEquals(Set.of("u->v", "v->w", "w->x"), actualLeaves.stream()
						.map(leaf -> leaf.getSubjectVar().getName() + "->" + leaf.getObjectVar().getName())
						.collect(Collectors.toSet()));
				List<BindingSetAssignment> finiteLeaves = new ArrayList<>();
				optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
					@Override
					public void meet(BindingSetAssignment leaf) {
						finiteLeaves.add(leaf);
					}
				});
				assertEquals(1, finiteLeaves.size());
				assertEquals(Set.of("u"), finiteLeaves.getFirst().getBindingNames());
				assertTrue(actualLeaves.stream()
						.allMatch(pattern -> pattern.getDoubleMetricPlanned("plannedFrontierStateId") > 0.0d),
						"Each statement-pattern input must retain its query-local Frontier state. plan="
								+ optimized);
				assertTrue(actualLeaves.stream()
						.map(pattern -> pattern
								.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE))
						.allMatch(source -> source != null && source.startsWith("frontier-v2-")
								|| "lmdb-frontier".equals(source)
								|| "lmdb-finite-binding-lookup".equals(source)),
						"Frontier leaves must keep either sampled provenance or stronger exact-access provenance. plan="
								+ optimized);
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void physicalLeafObservationVisitsLeftDeepAndBushyEvidenceTreesExactlyOnce(boolean bushy) {
		StatementPattern first = new StatementPattern(Var.of("u"), Var.of("p", SOCIAL_FOLLOWS), Var.of("v"));
		StatementPattern second = new StatementPattern(Var.of("v"), Var.of("p", SOCIAL_FOLLOWS), Var.of("w"));
		StatementPattern third = new StatementPattern(Var.of("w"), Var.of("p", SOCIAL_FOLLOWS), Var.of("x"));
		Join nested = bushy ? new Join(second, third) : new Join(first, second);
		Join root = bushy ? new Join(first, nested) : new Join(nested, third);
		Set<StatementPattern> leaves = physicalStatementInputs(List.of(root, nested));
		assertEquals(3, leaves.size());
		assertTrue(leaves.containsAll(List.of(first, second, third)));
	}

	private static Set<StatementPattern> physicalStatementInputs(List<Join> evidenceJoins) {
		Set<StatementPattern> leaves = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Join join : evidenceJoins) {
			join.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(StatementPattern leaf) {
					leaves.add(leaf);
				}
			});
		}
		return leaves;
	}

	private static boolean isFollowsBridge(StatementPattern node) {
		return node.getPredicateVar() != null
				&& SOCIAL_FOLLOWS.equals(node.getPredicateVar().getValue())
				&& node.getSubjectVar() != null && "u".equals(node.getSubjectVar().getName())
				&& node.getObjectVar() != null && "v".equals(node.getObjectVar().getName());
	}

	private static String mutualFollowsQuery() {
		StringJoiner userValues = new StringJoiner(" ");
		StringJoiner targetValues = new StringJoiner(" ");
		for (int i = 12; i <= 17; i++) {
			userValues.add("<" + socialUser(i).stringValue() + ">");
			targetValues.add("<" + socialUser(i).stringValue() + ">");
		}
		return "SELECT ?u ?v WHERE {\n"
				+ "  VALUES ?u { " + userValues + " }\n"
				+ "  VALUES ?v { " + targetValues + " }\n"
				+ "  ?u <" + SOCIAL_FOLLOWS.stringValue() + "> ?v .\n"
				+ "  FILTER (?u != ?v)\n"
				+ "  FILTER EXISTS { ?v <" + SOCIAL_FOLLOWS.stringValue() + "> ?u }\n"
				+ "}";
	}

	private static String repeatedFollowsChainQuery() {
		StringJoiner userValues = new StringJoiner(" ");
		for (int i = 12; i <= 17; i++) {
			userValues.add("<" + socialUser(i).stringValue() + ">");
		}
		return "SELECT ?u ?v ?w ?x WHERE {\n"
				+ "  VALUES ?u { " + userValues + " }\n"
				+ "  ?u <" + SOCIAL_FOLLOWS.stringValue() + "> ?v .\n"
				+ "  ?v <" + SOCIAL_FOLLOWS.stringValue() + "> ?w .\n"
				+ "  ?w <" + SOCIAL_FOLLOWS.stringValue() + "> ?x .\n"
				+ "}";
	}

	private static void loadSyntheticMutualFollowData(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.NONE);
			List<Resource> queryUsers = new ArrayList<>();
			for (int i = 12; i <= 17; i++) {
				queryUsers.add(socialUser(i));
			}
			for (Resource u : queryUsers) {
				for (Resource v : queryUsers) {
					if (!u.equals(v)) {
						connection.add(u, SOCIAL_FOLLOWS, v);
					}
				}
			}
			for (int i = 0; i < 1_500; i++) {
				Resource follower = socialUser(1_000 + i);
				Resource target = queryUsers.get(i % queryUsers.size());
				connection.add(follower, SOCIAL_FOLLOWS, target);
			}
			for (int i = 0; i < 1_500; i++) {
				Resource follower = queryUsers.get(i % queryUsers.size());
				Resource target = socialUser(3_000 + i);
				connection.add(follower, SOCIAL_FOLLOWS, target);
			}
			connection.commit();
		}
	}

	private static IRI socialUser(int index) {
		return VF.createIRI("http://example.com/theme/social/user/" + index);
	}
}
